import {piece,uid,clone,bounds,validateRoom} from './core.js';

export function createRoom(){return{name:'Meu quarto',active:true,w:3000,d:4000,h:2700,walls:'cutaway',wallColor:'#eeeae1',floorColor:'#cbb995',objects:[],door:{wall:'front',offset:2100,width:800,height:2100,bottom:0},window:{wall:'back',offset:1000,width:1000,height:1000,bottom:1100}};}
export const CATALOG=[
 {type:'bed',name:'Cama de solteiro',w:880,h:520,d:1880,icon:'bed'},
 {type:'double-bed',name:'Cama de casal',w:1380,h:520,d:1880,icon:'bed'},
 {type:'desk',name:'Bancada',w:1200,h:750,d:550,icon:'desk'},
 {type:'wardrobe',name:'Guarda-roupa',w:1200,h:2100,d:550,icon:'wardrobe'},
 {type:'chair',name:'Cadeira',w:450,h:850,d:500,icon:'chair'},
 {type:'box',name:'Volume livre',w:600,h:600,d:600,icon:'piece'}
];
export function createRoomObject(type,sourceProject){const item=CATALOG.find(v=>v.type===type);if(type==='custom'){if(!sourceProject?.pieces?.length)throw new Error('Desenhe ou abra um móvel antes de colocá-lo no quarto.');const b=bounds(sourceProject.pieces);return{id:uid(),name:sourceProject.name,type,x:50,y:0,z:50,w:b.max.x-b.min.x,h:b.max.y-b.min.y,d:b.max.z-b.min.z,rotation:0,material:null,source:clone(sourceProject.pieces)};}if(!item)throw new Error('Móvel desconhecido.');return{id:uid(),name:item.name,type,x:50,y:0,z:50,w:item.w,h:item.h,d:item.d,rotation:0,material:'oak'};}
export function footprint(o){const a=o.rotation*Math.PI/180,c=Math.cos(a),s=Math.sin(a),cx=o.x+o.w/2,cz=o.z+o.d/2;return[[-o.w/2,-o.d/2],[o.w/2,-o.d/2],[o.w/2,o.d/2],[-o.w/2,o.d/2]].map(([x,z])=>({u:cx+c*x+s*z,v:cz-s*x+c*z}));}
export function insideRoom(o,r){return o.y>=-.5&&o.y+o.h<=r.h+.5&&footprint(o).every(p=>p.u>=-.5&&p.u<=r.w+.5&&p.v>=-.5&&p.v<=r.d+.5);}
export function overlaps(a,b){if(a.y+a.h<=b.y+.5||b.y+b.h<=a.y+.5)return false;const A=footprint(a),B=footprint(b);for(const poly of [A,B])for(let i=0;i<4;i++){const p=poly[i],q=poly[(i+1)%4],axis={u:-(q.v-p.v),v:q.u-p.u},length=Math.hypot(axis.u,axis.v);axis.u/=length;axis.v/=length;const aa=A.map(p=>p.u*axis.u+p.v*axis.v),bb=B.map(p=>p.u*axis.u+p.v*axis.v);if(Math.max(...aa)<=Math.min(...bb)+.5||Math.max(...bb)<=Math.min(...aa)+.5)return false;}return true;}
export function solidsOverlap(a,b){if(a.decorative||b.decorative||!overlaps(a,b))return false;if(a.type!=='custom'&&b.type!=='custom')return true;
 const A=objectPieces({...a,doorsOpen:false}).map(p=>bounds([p])),B=objectPieces({...b,doorsOpen:false}).map(p=>bounds([p]));
 return A.some(a=>B.some(b=>['x','y','z'].every(k=>Math.min(a.max[k],b.max[k])-Math.max(a.min[k],b.min[k])>.5)));}
export function placementIssues(o,r){const list=[];if(!insideRoom(o,r))list.push('Fora dos limites do quarto');if(r.objects.some(p=>p.id!==o.id&&solidsOverlap(o,p)))list.push('Confira: peças sobrepostas a outro móvel');return list;}
export function findPlacement(o,r){for(let z=50;z<=r.d-o.d;z+=100)for(let x=50;x<=r.w-o.w;x+=100){const candidate={...o,x,z};if(insideRoom(candidate,r)&&!r.objects.some(p=>overlaps(candidate,p)))return{x,z};}return{x:50,z:50};}
function sourceFor(o){if(o.type==='custom')return o.source;const preset=CATALOG.find(p=>p.type===o.type),w=preset.w,h=preset.h,d=preset.d,part=(name,x,y,z,W,H,D,material='oak',fixed=false)=>({...piece(name,x,y,z,W,H,D,material),fixedMaterial:fixed});
 if(['bed','double-bed'].includes(o.type))return[part('Base',0,0,0,w,h*.55,d),part('Colchão',12,h*.55,12,w-24,h*.45,d-24,'white',true),part('Manta',14,h-12,d*.45,w-28,16,d*.52,'sage',true),part('Travesseiro',w*.12,h,45,w*.76,65,d*.21,'white',true)];
 if(o.type==='desk')return[part('Tampo',0,h-25,0,w,25,d),part('Lateral esquerda',0,0,0,25,h-25,d),part('Lateral direita',w-25,0,0,25,h-25,d),part('Travessa',25,h-220,0,w-50,170,18)];
 if(o.type==='wardrobe')return[part('Corpo',0,0,0,w,h,d),part('Porta esquerda',4,4,d,w/2-6,h-8,18,'white',true),part('Porta direita',w/2+2,4,d,w/2-6,h-8,18,'white',true),part('Puxador esquerdo',w/2-35,h*.43,d+18,10,h*.14,15,'walnut',true),part('Puxador direito',w/2+25,h*.43,d+18,10,h*.14,15,'walnut',true)];
 if(o.type==='chair'){const leg=35,seat=h*.52;return[part('Assento',0,seat,0,w,35,d),part('Encosto',0,seat+35,0,w,h-seat-35,35),...[[0,0],[w-leg,0],[0,d-leg],[w-leg,d-leg]].map(([x,z])=>part('Pé',x,0,z,leg,seat,leg))];}
 return[part('Volume',0,0,0,w,h,d)];
}
function partMatrix(p,o,b){const rx=p.rx*Math.PI/180,ry=p.ry*Math.PI/180,rz=p.rz*Math.PI/180,cx=Math.cos(rx),sx=Math.sin(rx),cy=Math.cos(ry),sy=Math.sin(ry),cz=Math.cos(rz),sz=Math.sin(rz),angle=o.rotation*Math.PI/180,C=Math.cos(angle),S=Math.sin(angle);const f=(x,y,z)=>{let a=x*cz-y*sz,k=x*sz+y*cz,l=z,m=a*cy+l*sy,n=-a*sy+l*cy;let X=m+p.x+p.w/2,Y=k*cx-n*sx+p.y+p.h/2,Z=k*sx+n*cx+p.z+p.d/2;X=(X-(b.min.x+b.max.x)/2)*o.w/(b.max.x-b.min.x);Y=(Y-(b.min.y+b.max.y)/2)*o.h/(b.max.y-b.min.y);Z=(Z-(b.min.z+b.max.z)/2)*o.d/(b.max.z-b.min.z);return[C*X+S*Z+o.x+o.w/2,Y+o.y+o.h/2,-S*X+C*Z+o.z+o.d/2];};const t=f(0,0,0),a=f(1,0,0),c=f(0,1,0),d=f(0,0,1);return[a[0]-t[0],a[1]-t[1],a[2]-t[2],0,c[0]-t[0],c[1]-t[1],c[2]-t[2],0,d[0]-t[0],d[1]-t[1],d[2]-t[2],0,...t,1];}
function doorPose(p,o){if(!o.doorsOpen||!p.door)return p;const left=p.hingeSide==='left',angle=(left?1:-1)*Math.PI/2,hingeX=p.x+p.w/2,hingeZ=left?p.z:p.z+p.d,dx=0,dz=(left?1:-1)*p.d/2;return{...p,x:hingeX+Math.cos(angle)*dx+Math.sin(angle)*dz-p.w/2,z:hingeZ-Math.sin(angle)*dx+Math.cos(angle)*dz-p.d/2,ry:(left?90:-90)};}
export function objectPieces(o){const source=sourceFor(o),b=bounds(source);return source.map(original=>{const p=doorPose(original,o);return{...p,id:o.id,matrix:partMatrix(p,o,b),color:o.material&&!p.fixedMaterial?undefined:p.color,material:p.fixedMaterial?p.material:(o.material||p.material)};});}
function wallPart(wall,start,bottom,length,height,r,thickness=100){if(length<.1||height<.1)return null;const W=['back','front'].includes(wall);return{...piece('Parede',W?start:wall==='left'?-thickness:r.w,bottom,W?(wall==='back'?-thickness:r.d):start,W?length:thickness,height,W?thickness:length,'white'),id:'@wall-'+uid(),environment:true,wall,color:r.wallColor};}
function openingParts(wall,o,r,type){const arr=[],along=['back','front'].includes(wall),normal=wall==='back'?-20:wall==='front'?r.d:wall==='left'?-20:r.w;function add(start,y,width,height,thick,color){const p=piece(type,along?start:normal,y,along?normal:start,along?width:thick,height,along?thick:width,'white');p.id='@opening-'+uid();p.environment=true;p.wall=wall;p.color=color;arr.push(p);}const a=o.offset,b=o.bottom,w=o.width,h=o.height;add(a,b,35,h,90,'#faf9f3');add(a+w-35,b,35,h,90,'#faf9f3');add(a,b+h-35,w,35,90,'#faf9f3');if(type==='window'){add(a,b,w,35,90,'#faf9f3');add(a+35,b+35,w-70,h-70,12,'#c6d9db');add(a+w/2-15,b+35,30,h-70,45,'#faf9f3');}else add(a+35,b+8,w-70,h-43,28,'#c6ac83');return arr;}
export function roomEnvironment(r){const floor={...piece('Piso',0,-80,0,r.w,80,r.d),id:'@floor',environment:true,color:r.floorColor},result=[floor],walls=r.walls==='all'?['back','left','front','right']:r.walls==='interior'?['back','left','right']:r.walls==='cutaway'?['back','left']:[];for(const wall of walls){const length=['back','front'].includes(wall)?r.w:r.d,openings=[r.door,r.window].filter(o=>o&&o.wall===wall);let rectangles=[{x:0,y:0,w:length,h:r.h}];for(const o of openings){const next=[];for(const q of rectangles){const x1=Math.max(q.x,o.offset),x2=Math.min(q.x+q.w,o.offset+o.width),y1=Math.max(q.y,o.bottom),y2=Math.min(q.y+q.h,o.bottom+o.height);if(x2<=x1||y2<=y1){next.push(q);continue;}if(x1>q.x)next.push({x:q.x,y:q.y,w:x1-q.x,h:q.h});if(x2<q.x+q.w)next.push({x:x2,y:q.y,w:q.x+q.w-x2,h:q.h});if(y1>q.y)next.push({x:x1,y:q.y,w:x2-x1,h:y1-q.y});if(y2<q.y+q.h)next.push({x:x1,y:y2,w:x2-x1,h:q.y+q.h-y2});}rectangles=next;}for(const q of rectangles){const p=wallPart(wall,q.x,q.y,q.w,q.h,r);if(p)result.push(p);}for(const type of ['door','window'])if(r[type]?.wall===wall)result.push(...openingParts(wall,r[type],r,type));}return result;}
export function roomScene(project){const r=project.room;return{version:1,name:r.name,w:r.w,h:r.h,d:r.d,unit:project.unit||'cm',roomView:true,presentationView:null,pieces:[...roomEnvironment(r),...r.objects.flatMap(objectPieces)]};}
export function validateRoomCopy(room){return validateRoom(clone(room));}
